def maximum_hourglass_sum(grid):
    best=-10**30
    for row in range(len(grid)-2):
        for column in range(len(grid[0])-2):
            total=sum(grid[row][column:column+3])+grid[row+1][column+1]+sum(grid[row+2][column:column+3]);best=max(best,total)
    return best

